ALTER TABLE finance_events DROP CONSTRAINT finance_events_event_type_check;
ALTER TABLE finance_events ADD CONSTRAINT finance_events_event_type_check CHECK (event_type IN ('CHARGE_RECORDED','PAYMENT_RECORDED','PAYMENT_CONFIRMED','PAYMENT_DISPUTED','PAYMENT_REVERSED','ADJUSTMENT_RECORDED','REFUND_REQUESTED','REFUND_APPROVED','REFUND_REJECTED','REFUND_EXECUTION_RECORDED','RECONCILIATION_CLOSED'));
